const menu=document.querySelector('.menu'),nav=document.querySelector('.nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Fechar menu':'Abrir menu')});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));const models={S9:{image:'assets/VELORA_S9_02_lateral.webp',type:'SEDÃ CONCEITUAL',description:'Linhas fluidas, presença marcante e uma experiência pensada para transformar cada chegada.',trait:'Elegância',number:'01'},X7:{image:'assets/VELORA_X7_02_lateral.webp',type:'SUV CONCEITUAL',description:'Uma presença imponente para explorar novos caminhos, com espaço para tudo o que move você.',trait:'Versatilidade',number:'02'}};document.querySelectorAll('.model-tab').forEach(tab=>tab.addEventListener('click',()=>{const name=tab.dataset.model,model=models[name];document.querySelectorAll('.model-tab').forEach(t=>{t.classList.toggle('active',t===tab);t.setAttribute('aria-selected',String(t===tab))});document.querySelector('#modelImage').src=model.image;document.querySelector('#modelImage').alt=`VELORA ${name} visto de lado`;document.querySelector('#modelName').textContent=name;document.querySelector('#modelType').textContent=model.type;document.querySelector('#modelDescription').textContent=model.description;document.querySelector('#modelTrait').textContent=model.trait;document.querySelector('#modelNumber').textContent=model.number}));
